<script setup lang="ts">
import { ref, watch } from 'vue'; import { api, type Selection, type CreditResult as CreditData, type Row } from '../api'; import { origins, methods, iso, date, number } from '../utils'; import AssetSelect from '../components/AssetSelect.vue'; import AsyncPanel from '../components/AsyncPanel.vue'; import CreditResult from '../components/CreditResult.vue'; import LineChart from '../components/LineChart.vue'; import JsonDetails from '../components/JsonDetails.vue'
const selection=ref<Selection>({asset_id:'',version:''}), origin=ref('local_operational'),method=ref('decay30'),at=ref(''),result=ref<CreditData|null>(null),series=ref<Row[]>([]),events=ref<Row[]>([]),loading=ref(false),error=ref('')
async function assess(){loading.value=true;error.value='';result.value=null;series.value=[];events.value=[];const f={origin:origin.value,method:method.value,at:iso(at.value)};try{const [r,s,a]=await Promise.all([api.credit(selection.value,f),api.series(selection.value,f),api.audit({asset_id:selection.value.asset_id,origin:origin.value,to:f.at})]);result.value=r;series.value=s.points??[];events.value=a.events??[]}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
watch([selection,origin,method,at],()=>{result.value=null;series.value=[];events.value=[]},{deep:true})
</script>
<template><section class="panel"><div class="panel-heading"><div><p class="eyebrow">EVIDENCE-DRIVEN BAYESIAN CREDIT</p><h2>选择独立的信用来源与评估时点</h2></div></div><AssetSelect v-model="selection"/><div class="form-grid three"><label>证据来源<select v-model="origin" aria-label="信用来源"><option v-for="o in origins" :key="o.value" :value="o.value">{{ o.label }} / {{ o.value }}</option></select></label><label>信用算法<select v-model="method" aria-label="信用算法"><option v-for="m in methods" :key="m.value" :value="m.value">{{ m.label }}</option></select></label><label>评估时点（本地时间，留空为当前）<input v-model="at" type="datetime-local" aria-label="信用评估时点"></label></div><div class="actions"><button class="button" :disabled="loading||!selection.asset_id" @click="assess">计算信用与历史曲线</button><span class="muted small">{{ origins.find(o=>o.value===origin)?.note }}</span></div></section><AsyncPanel :loading="loading" :error="error" @retry="assess"><template v-if="result"><CreditResult :result="result"/><section class="panel"><LineChart :points="series.map(p=>({x:date(p.at),y:p.q,lower:p.q_lower,upper:p.q_upper,reason:p.reason}))" :fixed-range="[0,1]" title="履约信用随可用证据变化" unit="纵轴 q（0–1）；阴影为模型条件区间"/><p class="footnote">按照服务端事件/观测时间回放，未来证据不会进入过去的信用；曲线变动不代表现实企业信用变化。</p><div class="table-wrap"><table><thead><tr><th>可用时点</th><th>q</th><th>有效合同</th><th>变化原因</th></tr></thead><tbody><tr v-for="(p,i) in series" :key="i"><td>{{ date(p.at) }}</td><td>{{ number(p.q,4) }}</td><td>{{ p.n_history }}</td><td>{{ p.reason }}</td></tr><tr v-if="!series.length"><td colspan="4" class="empty-cell">没有历史观测节点</td></tr></tbody></table></div></section><section class="panel"><h2>相关可验证事件</h2><p class="muted">来源单独筛选；事件本身不是额外的一次成功或失败合同。</p><JsonDetails :data="events" title="查看对应审计事件和签名验证记录"/></section></template><section v-else class="panel empty-intro"><span>◉</span><h3>先选证据来源，再解读概率</h3><p>同一资产的自然试交付、人工故障与历史模拟不得合并成一个信用分。</p></section></AsyncPanel></template>
